<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $title ?? 'Quotely' }}</title><style>
:root{--ink:#17211d;--muted:#68736d;--brand:#166c4d;--pale:#eef6f1;--line:#dce5df;--paper:#fff;--cream:#f7f8f4}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:15px/1.5 system-ui,-apple-system,sans-serif}nav{height:70px;background:#10261d;color:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 max(24px,calc((100% - 1120px)/2))}nav a{color:#fff;text-decoration:none}.brand{font-size:22px;font-weight:800;letter-spacing:-.5px}.wrap{max-width:1120px;margin:42px auto;padding:0 24px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:28px}h1{font-size:34px;line-height:1.15;margin:0 0 6px;letter-spacing:-1px}h2{margin:0 0 18px}p{color:var(--muted)}.btn{display:inline-block;border:0;border-radius:9px;padding:11px 17px;background:var(--brand);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.secondary{background:#fff;color:var(--ink);border:1px solid var(--line)}.btn.danger{background:#9c342d}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:22px;box-shadow:0 3px 14px #17211d0a}.metric{font-size:29px;font-weight:800}.muted{color:var(--muted)}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:14px 10px;border-bottom:1px solid var(--line)}th{font-size:12px;text-transform:uppercase;color:var(--muted)}.badge{display:inline-block;border-radius:99px;padding:4px 9px;background:var(--pale);color:var(--brand);font-size:12px;font-weight:800;text-transform:capitalize}.alert{padding:13px 16px;border-radius:9px;background:#dff3e6;color:#185d37;margin-bottom:20px}label{font-weight:700;display:block;margin:14px 0 6px}input,select,textarea{width:100%;border:1px solid #cdd8d1;border-radius:8px;padding:11px;background:#fff;font:inherit}textarea{min-height:90px}.row{display:grid;grid-template-columns:1fr 110px 160px;gap:12px}.error{color:#9c342d;font-size:13px